# filter: keep maximal
print("tandem repeat arrays (unit, copies, start, end):")
seen=set()
for a,b,p in t:
    key=(a,p)
    if key in seen: continue
    seen.add(key)
    if b-a>=12: print(f"  unit {p} nt x{(b-a)//p} at {a}-{b}: {seq[a-1:a-1+p]}")
